  function statCard(label,value,change,ico,tone,sub='vs. previous period'){return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${tone}">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><span class="trend ${change==='—'?'neutral':''}">${change}</span><span>${sub}</span></div></article>`}
  function chartSvg(){const vals=chartRange==='7days'?[310,440,385,590,530,710,920]:chartRange==='30days'?[520,480,660,590,780,740,900]:[290,350,315,450,480,430,610];const max=Math.max(...vals)*1.2;const points=vals.map((v,i)=>[35+i*61,183-(v/max)*145]);const path=points.map((p,i)=>`${i?'L':'M'} ${p[0]} ${p[1]}`).join(' ');const area=`${path} L ${points.at(-1)[0]} 190 L ${points[0][0]} 190 Z`;const labels=chartRange==='7days'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:chartRange==='30days'?['1–4','5–8','9–12','13–16','17–20','21–24','25–30']:['Jan','Feb','Mar','Apr','May','Jun','Jul'];return `<svg class="sales-chart" viewBox="0 0 430 220" role="img" aria-label="Illustrative sales trend chart"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#4777f5" stop-opacity=".22"/><stop offset="100%" stop-color="#4777f5" stop-opacity=".01"/></linearGradient></defs>${[35,75,115,155,195].map(y=>`<line class="chart-grid" x1="30" y1="${y}" x2="410" y2="${y}"/>`).join('')}<path class="chart-area" d="${area}"/><path class="chart-line" d="${path}"/>${points.map(p=>`<circle class="chart-point" cx="${p[0]}" cy="${p[1]}" r="3.5"/>`).join('')}${labels.map((l,i)=>`<text class="chart-label" x="${35+i*61}" y="214" text-anchor="middle">${l}</text>`).join('')}</svg>`}
